questionvariables.text:
/* Autor: Florian Lindemann (TU München) & Team */
/* Nutzung und Weitergabe nach Absprache: lindemann@tum.de */
/* überarbeitet von Matteo Mertz (TU München) */

Nsm: 5; /* [EDIT] Change this number to match the number of statements you want to test */

/* [START] DO NOT CHANGE BLOCK */

/* sm[i] = i-th statement */
sm: makelist("", i, 1, Nsm);
/* rpsm[i] = randomisation parameter for statement sm[i]  */
rp_sm: makelist(0, i, 1, Nsm);
/* sol_sm[i] = truth-value of statement sm[i] */
sol_sm: makelist(false, i, 1, Nsm);

/* [END] DO NOT CHANGE BLOCK */

/* 
STATEMENTS
*/

/* Statements (entries in the list "sm"), their random parameters (entries in the list "rp_sm"), and their truth-values (entries in the list "sol_sm") depending on the randomisation parameter. */
/* [EDIT] (1) Adjust the &list& in "rpsm[sm_counter]: rand(&list&)" to the intended selection of variants of the statements, (2) give the variants of the statements (copy-paste another "if"-block per variant), (3) set the truth-values of the variants. */

/* Statement 1 */
sm_counter: 1;
rp_sm[sm_counter]: rand([1]);
if rp_sm[sm_counter]=1 then (
  sm[sm_counter]: "\\(1+\\sum\\limits_{n=1}^{\\infty} (-1)^n \\frac{2^ {2n-1} x^{2n}}{(2n)!}\\)",
  sol_sm[sm_counter]: true
);

/* [START] Block to copy for additional statements */
/* Statement 2 */
sm_counter: sm_counter+1;
rp_sm[sm_counter]: rand([1,2]);
if rp_sm[sm_counter]=1 then (
  sm[sm_counter]: "\\(1+\\sum\\limits_{n=0}^{\\infty} (-1)^n \\frac{2^{2n-1} x^{2n}}{(2n)!}\\)",
  sol_sm[sm_counter]: false
);
if rp_sm[sm_counter]=2 then (
  sm[sm_counter]: "\\(\\frac12-\\sum\\limits_{n=0}^{\\infty} (-1)^n \\frac{2^ {2n-1} x^{2n}}{(2n)!}\\)",
  sol_sm[sm_counter]: false
);
/* [END] Block to copy for additional statements */

/* Statement 3 */
sm_counter: sm_counter+1;
rp_sm[sm_counter]: rand([1,2]);
if rp_sm[sm_counter]=1 then (
  sm[sm_counter]: "\\(\\sum\\limits_{n=0}^{\\infty} (-1)^n \\frac{(2x)^{2n}}{(2n)!}\\)",
  sol_sm[sm_counter]: false
);
if rp_sm[sm_counter]=2 then (
  sm[sm_counter]: "\\(\\sum\\limits_{n=0}^{\\infty} (-1)^n \\frac{x^{4n}}{(2n)!}\\)",
  sol_sm[sm_counter]: false
);

/* Statement 4 */
sm_counter: sm_counter+1;
rp_sm[sm_counter]: rand([1]);
if rp_sm[sm_counter]=1 then (
  sm[sm_counter]: "\\(\\sum\\limits_{n=1}^{\\infty} (-1)^n \\frac{2^ {2n-1} x^{2n}}{(2n)!}\\)",
  sol_sm[sm_counter]: false
);

/* Statement 5 */
sm_counter: sm_counter+1;
rp_sm[sm_counter]: rand([1]);
if rp_sm[sm_counter]=1 then (
  sm[sm_counter]: "\\(\\frac{1}{2} + \\frac{1}{2} \\sum\\limits_{n=0}^{\\infty} (-1)^n \\frac{(2x)^{2n}}{(2n)!}\\)",
  sol_sm[sm_counter]: true
);

/* [EDIT] For each new statement, add another if-block analogously to the one with "sm_counter: sm_counter+1". */

/*
OPTIONS
*/

/* This will be shown in the general feedback block for each statement respectively. */
/* [EDIT] If you want to change these texts do so in the following two lines. */
sol_text1: "Diese Reihe ist eine KORREKTE Reihendarstellung von \\(\\cos^2(x)\\).";
sol_text2: "Diese Reihe ist KEINE Reihendarstellung von \\(\\cos^2(x)\\).";

/* [START] DO NOT CHANGE BLOCK */

/* TEACHER ANSWERS */
/* tans = (permutated)) teacher answers */
perm: random_permutation(makelist(i,i,1,Nsm));
tans: makelist([],i,1,Nsm);
for i in makelist(i,i,1,Nsm) do 
  tans[i]: [i, sol_sm[perm[i]], sm[perm[i]]]; 

taB: tans;

/* HELPER FUNCTIONS */
statement(n) := sm[perm[n]];
feedback(n) := if sol_sm[perm[n]] then sol_text1 else sol_text2;

/* [END] DO NOT CHANGE BLOCK */

feedbackvariables.text:
/* 
ans1 = list of the CAS values assigned to the selected options 
mcq_correct(tans) = list of the CAS values assigned to the correct (true) options
mcq_incorrect(tans) = list of the CAS values assigned to the incorrect (false) options
*/

numOptions: length(tans);

correctOptionValues: mcq_correct(tans);
incorrectOptionValues: mcq_incorrect(tans);

numCorrectOptions: length(correctOptionValues);
numIncorrectOptions: length(incorrectOptionValues);

correctInputs: sublist(ans1, lambda([x], member(x, correctOptionValues))); /* creates a list of all elements of ans1 that are values of the correct (=in tans as true) options */
incorrectInputs: sublist(ans1, lambda([x], member(x, incorrectOptionValues))); /* creates a list of all elements of ans1 that are values of the incorrect (=in tans as false) options */

numCorrectlySelected: length(correctInputs);
numCorrectlyNotSelected: numIncorrectOptions - length(incorrectInputs);

mark: (numCorrectlySelected + numCorrectlyNotSelected) / numOptions;
